sql:
SELECT uf FROM municipios WHERE regiao = 'S' AND nome IN (
    SELECT municipio_id FROM postos WHERE cnpj IN (
        SELECT posto_id FROM coletas WHERE produto = 'ETANOL' AND data_coleta BETWEEN '2026-03-01' AND '2026-06-30'
    )
) ORDER BY AVG(valor_venda) ASC LIMIT 1

